public List<Integer> findAnagrams(String s, String p) {
    List<Integer> res = new ArrayList<>();
    int n = s.length(), m = p.length();
    if (n < m) return res;
    int[] need = new int[26], win = new int[26];
    for (int i = 0; i < m; i++) need[p.charAt(i) - 'a']++;
    for (int i = 0; i < n; i++) {
        win[s.charAt(i) - 'a']++;
        if (i >= m) win[s.charAt(i - m) - 'a']--;
        if (i >= m - 1 && Arrays.equals(win, need)) res.add(i - m + 1);
    }
    return res;
}

public int distinctEchoSubstrings(String text) {
    int n = text.length();
    final long MOD1 = 1_000_000_007L, MOD2 = 998_244_353L, B1 = 131, B2 = 137;
    long[] h1 = new long[n + 1], h2 = new long[n + 1];
    long[] p1 = new long[n + 1], p2 = new long[n + 1];
    p1[0] = p2[0] = 1;
    for (int i = 0; i < n; i++) {
        h1[i + 1] = (h1[i] * B1 + text.charAt(i)) % MOD1;
        h2[i + 1] = (h2[i] * B2 + text.charAt(i)) % MOD2;
        p1[i + 1] = p1[i] * B1 % MOD1;
        p2[i + 1] = p2[i] * B2 % MOD2;
    }
    Set<Long> seen = new HashSet<>();
    for (int len = 1; 2 * len <= n; len++) {
        for (int i = 0; i + 2 * len <= n; i++) {
            long a1 = sub(h1, p1, i, i + len, MOD1);
            long b1 = sub(h1, p1, i + len, i + 2 * len, MOD1);
            if (a1 != b1) continue;
            long a2 = sub(h2, p2, i, i + len, MOD2);
            long b2 = sub(h2, p2, i + len, i + 2 * len, MOD2);
            if (a2 == b2) seen.add(a1 * MOD2 + a2);
        }
    }
    return seen.size();
}

private long sub(long[] h, long[] p, int l, int r, long mod) {
    return (h[r] - h[l] * p[r - l] % mod + mod) % mod;
}

public String longestDupSubstring(String s) {
    int n = s.length();
    final long MOD1 = 1_000_000_007L, MOD2 = 998_244_353L, B1 = 131, B2 = 137;
    long[] h1 = new long[n + 1], h2 = new long[n + 1];
    long[] p1 = new long[n + 1], p2 = new long[n + 1];
    p1[0] = p2[0] = 1;
    for (int i = 0; i < n; i++) {
        h1[i + 1] = (h1[i] * B1 + s.charAt(i)) % MOD1;
        h2[i + 1] = (h2[i] * B2 + s.charAt(i)) % MOD2;
        p1[i + 1] = p1[i] * B1 % MOD1;
        p2[i + 1] = p2[i] * B2 % MOD2;
    }
    int lo = 1, hi = n - 1, start = -1, len = 0;
    while (lo <= hi) {
        int mid = (lo + hi) >>> 1;
        int pos = find(mid, n, h1, h2, p1, p2, MOD1, MOD2);
        if (pos >= 0) { start = pos; len = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    return start < 0 ? "" : s.substring(start, start + len);
}

private int find(int L, int n, long[] h1, long[] h2,
                 long[] p1, long[] p2, long MOD1, long MOD2) {
    Set<Long> seen = new HashSet<>();
    for (int i = 0; i + L <= n; i++) {
        long a = (h1[i + L] - h1[i] * p1[L] % MOD1 + MOD1) % MOD1;
        long b = (h2[i + L] - h2[i] * p2[L] % MOD2 + MOD2) % MOD2;
        long key = a * MOD2 + b;
        if (!seen.add(key)) return i;   // duplicate window found
    }
    return -1;
}

public boolean differByOne(String[] dict) {
    int n = dict.length, m = dict[0].length();
    final long MOD = 1_000_000_007L, B = 131;
    long[] pow = new long[m];
    pow[0] = 1;
    for (int j = 1; j < m; j++) pow[j] = pow[j - 1] * B % MOD;
    long[] hash = new long[n];
    for (int i = 0; i < n; i++) {
        long h = 0;
        for (int j = 0; j < m; j++)
            h = (h + dict[i].charAt(j) * pow[m - 1 - j]) % MOD;
        hash[i] = h;
    }
    for (int j = 0; j < m; j++) {
        Map<Long, List<Integer>> seen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long masked = (hash[i] - dict[i].charAt(j) * pow[m - 1 - j] % MOD + MOD) % MOD;
            List<Integer> lst = seen.computeIfAbsent(masked, k -> new ArrayList<>());
            for (int prev : lst)
                if (differExactlyOne(dict[prev], dict[i])) return true;
            lst.add(i);
        }
    }
    return false;
}

private boolean differExactlyOne(String a, String b) {
    int diff = 0;
    for (int i = 0; i < a.length(); i++)
        if (a.charAt(i) != b.charAt(i) && ++diff > 1) return false;
    return diff == 1;
}

public int fib(long n) {
    final long MOD = 1_000_000_007L;
    if (n == 0) return 0;
    long[][] r = matpow(new long[][]{{1, 1}, {1, 0}}, n, MOD);
    return (int) r[0][1];          // F(n)
}

private long[][] matpow(long[][] m, long p, long MOD) {
    int k = m.length;
    long[][] res = new long[k][k];
    for (int i = 0; i < k; i++) res[i][i] = 1;   // identity
    while (p > 0) {
        if ((p & 1) == 1) res = mul(res, m, MOD);
        m = mul(m, m, MOD);
        p >>= 1;
    }
    return res;
}

private long[][] mul(long[][] a, long[][] b, long MOD) {
    int n = a.length, m = b[0].length, k = b.length;
    long[][] c = new long[n][m];
    for (int i = 0; i < n; i++)
        for (int x = 0; x < k; x++) {
            if (a[i][x] == 0) continue;
            for (int j = 0; j < m; j++)
                c[i][j] = (c[i][j] + a[i][x] * b[x][j]) % MOD;
        }
    return c;
}

public int countPaths(int[][] adj, int k, int src, int dst) {
    final long MOD = 1_000_000_007L;
    int n = adj.length;
    long[][] a = new long[n][n];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            a[i][j] = adj[i][j];
    long[][] r = matpow(a, k, MOD);
    return (int) r[src][dst];
}

