public int knightDialer(int n) {
    final long MOD = 1_000_000_007L;
    int[][] moves = {
        {4, 6}, {6, 8}, {7, 9}, {4, 8}, {0, 3, 9},
        {}, {0, 1, 7}, {2, 6}, {1, 3}, {2, 4}
    };
    long[] dp = new long[10];
    Arrays.fill(dp, 1);
    for (int step = 1; step < n; step++) {
        long[] next = new long[10];
        for (int d = 0; d < 10; d++)
            for (int nb : moves[d])
                next[nb] = (next[nb] + dp[d]) % MOD;
        dp = next;
    }
    long sum = 0;
    for (long v : dp) sum = (sum + v) % MOD;
    return (int) sum;
}

public int knightDialer(int n) {
    final long MOD = 1_000_000_007L;
    int[][] moves = {
        {4, 6}, {6, 8}, {7, 9}, {4, 8}, {0, 3, 9},
        {}, {0, 1, 7}, {2, 6}, {1, 3}, {2, 4}
    };
    long[][] T = new long[10][10];
    for (int d = 0; d < 10; d++)
        for (int nb : moves[d])
            T[nb][d] = 1;                      // nb <- d
    long[][] P = matpow(T, n - 1, MOD);        // T^(n-1)
    long sum = 0;
    for (int i = 0; i < 10; i++)
        for (int j = 0; j < 10; j++)
            sum = (sum + P[i][j]) % MOD;        // apply to all-ones start
    return (int) sum;
}

