public int checkRecord(int n) {
    final long MOD = 1_000_000_007L;
    long[][] dp = new long[2][3];      // dp[absences][trailing L]
    dp[0][0] = 1;
    for (int i = 0; i < n; i++) {
        long[][] nd = new long[2][3];
        for (int a = 0; a < 2; a++)
            for (int l = 0; l < 3; l++) {
                long cur = dp[a][l];
                if (cur == 0) continue;
                nd[a][0] = (nd[a][0] + cur) % MOD;              // append P
                if (a == 0) nd[1][0] = (nd[1][0] + cur) % MOD;  // append A
                if (l < 2) nd[a][l + 1] = (nd[a][l + 1] + cur) % MOD; // append L
            }
        dp = nd;
    }
    long sum = 0;
    for (int a = 0; a < 2; a++)
        for (int l = 0; l < 3; l++)
            sum = (sum + dp[a][l]) % MOD;
    return (int) sum;
}

public int checkRecord(int n) {
    final long MOD = 1_000_000_007L;
    // states 0..5 = (a,l): 0=(0,0) 1=(0,1) 2=(0,2) 3=(1,0) 4=(1,1) 5=(1,2)
    long[][] T = new long[6][6];       // T[to][from]
    int[][] al = {{0,0},{0,1},{0,2},{1,0},{1,1},{1,2}};
    for (int s = 0; s < 6; s++) {
        int a = al[s][0], l = al[s][1];
        add(T, idx(a, 0), s);                  // P
        if (a == 0) add(T, idx(1, 0), s);      // A
        if (l < 2) add(T, idx(a, l + 1), s);   // L
    }
    long[][] P = matpow(T, n, MOD);
    // initial vector = state (0,0) only -> sum of column 0 of P
    long sum = 0;
    for (int i = 0; i < 6; i++) sum = (sum + P[i][0]) % MOD;
    return (int) sum;
}

private int idx(int a, int l) { return a * 3 + l; }
private void add(long[][] T, int to, int from) { T[to][from]++; }

private long[][] matpow(long[][] m, long p, long MOD) {
    int k = m.length;
    long[][] res = new long[k][k];
    for (int i = 0; i < k; i++) res[i][i] = 1;
    while (p > 0) {
        if ((p & 1) == 1) res = mul(res, m, MOD);
        m = mul(m, m, MOD);
        p >>= 1;
    }
    return res;
}

private long[][] mul(long[][] a, long[][] b, long MOD) {
    int n = a.length, m = b[0].length, k = b.length;
    long[][] c = new long[n][m];
    for (int i = 0; i < n; i++)
        for (int x = 0; x < k; x++) {
            if (a[i][x] == 0) continue;
            for (int j = 0; j < m; j++)
                c[i][j] = (c[i][j] + a[i][x] * b[x][j]) % MOD;
        }
    return c;
}

public int numWays(int steps, int arrLen) {
    final long MOD = 1_000_000_007L;
    int maxPos = Math.min(steps / 2, arrLen - 1);
    long[] dp = new long[maxPos + 1];
    dp[0] = 1;
    for (int s = 0; s < steps; s++) {
        long[] nd = new long[maxPos + 1];
        for (int p = 0; p <= maxPos; p++) {
            long cur = dp[p];
            if (cur == 0) continue;
            nd[p] = (nd[p] + cur) % MOD;                       // stay
            if (p > 0) nd[p - 1] = (nd[p - 1] + cur) % MOD;    // left
            if (p < maxPos) nd[p + 1] = (nd[p + 1] + cur) % MOD; // right
        }
        dp = nd;
    }
    return (int) dp[0];
}
